#include <cuda_runtime.h>
#include <vector>
#include <string>
#include <fstream>
#include <algorithm>
#include "corrected_selected_kernel.cuh"
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}while(0)
constexpr int GUARD=16384;
std::vector<double>load(const char*name,size_t n){std::ifstream f(name,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=(std::streamoff)(n*8))exit(3);f.seekg(0);std::vector<double>a(n);f.read((char*)a.data(),n*8);if(!f)exit(3);return a;}
template<class T>struct Buffer{size_t n;T*base,*data;std::vector<T>initial,host;Buffer(int N,T value):n(N),initial(n+16,GUARD),host(n+16){std::fill(initial.begin()+8,initial.begin()+8+n,value);CK(cudaMalloc(&base,(n+16)*sizeof(T)));data=base+8;copyin();}Buffer(int N,const std::vector<double>&pre,size_t&pos):Buffer(N,T(0)){for(size_t i=0;i<n;++i)initial[8+i]=pre[pos++];copyin();}void copyin(){CK(cudaMemcpy(base,initial.data(),initial.size()*sizeof(T),cudaMemcpyHostToDevice));}void read(){CK(cudaMemcpy(host.data(),base,host.size()*sizeof(T),cudaMemcpyDeviceToHost));}};
struct Case{int R,F,G,Q,FAI,repeat,mode;Buffer<float>src,flux,sig,state,scratch;Buffer<int>qid,fid;
Case(int r,int f,int g,int q,int a,int rep,int mo,const std::vector<double>&pre,size_t&pos):R(r),F(f),G(g),Q(q),FAI(a),repeat(rep),mode(mo),src(R*F*G,pre,pos),flux(R*F*G,pre,pos),sig(R*G,pre,pos),state(G,pre,pos),scratch(14*G,-777.f),qid(1,q),fid(1,a){}
std::vector<double>execute(double&seconds,bool&ok){flux.copyin();state.copyin();scratch.copyin();flux.read();state.read();auto beforef=flux.host,befores=state.host;ok&=beforef==flux.initial&&befores==state.initial;CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;++rep)att<<<128,128>>>(qid.data,fid.data,flux.data,src.data,sig.data,state.data,scratch.data,F,G,1);CK(cudaDeviceSynchronize());seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();src.read();flux.read();sig.read();state.read();scratch.read();qid.read();fid.read();std::vector<double>out;auto payload=[&](auto&x){for(size_t i=0;i<x.n;++i)out.push_back(x.host[8+i]);};payload(flux);payload(state);payload(scratch);payload(src);payload(sig);for(size_t i=0;i<flux.n;++i)out.push_back(beforef[8+i]);for(size_t i=0;i<state.n;++i)out.push_back(befores[8+i]);payload(qid);payload(fid);ok&=src.host==src.initial&&sig.host==sig.initial&&qid.host==qid.initial&&fid.host==fid.initial;for(int r=0;r<R;++r)for(int j=0;j<F;++j)if(r!=Q||j!=FAI)for(int g=0;g<G;++g){int i=(r*F+j)*G+g;ok&=flux.host[8+i]==flux.initial[8+i];}auto guard=[&](auto&x){for(size_t i=0;i<x.host.size();++i)if(i<8||i>=x.n+8){out.push_back(x.host[i]);ok&=x.host[i]==GUARD;}};guard(src);guard(flux);guard(sig);guard(state);guard(scratch);guard(qid);guard(fid);for(int g=0;g<G;++g)ok&=state.host[8+g]>=-2e-5&&scratch.host[8+8*G+g]>=-2e-5;return out;}
};
int main(){auto pre=load(FIXTURE,6023),gold=load(ORACLE,13164);size_t pos=1;std::vector<Case*>cases;for(int c=0;c<6;++c){int R=pre[pos++],F=pre[pos++],G=pre[pos++],Q=pre[pos++],FAI=pre[pos++],rep=pre[pos++],mode=pre[pos++];cases.push_back(new Case(R,F,G,Q,FAI,rep,mode,pre,pos));}if(pos!=pre.size())return 3;for(auto c:cases){double sec;bool ok=true;c->execute(sec,ok);if(!ok)return 4;}
for(int trial=1;trial<=5;++trial){auto art=pre;std::vector<double>times;bool ok=true;double ma=0;for(auto c:cases){double sec;auto vals=c->execute(sec,ok);art.insert(art.end(),vals.begin(),vals.end());times.push_back(sec);}if(art.size()!=pre.size()+gold.size())return 3;for(size_t i=0;i<gold.size();++i){double actual=art[pre.size()+i],error=fabs(actual-gold[i]);ok&=std::isfinite(actual)&&error<=2e-5+2e-5*fabs(gold[i]);ma=std::max(ma,error);}std::string path="output_trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)art.data(),art.size()*8);if(!f)return 3;double total=0;for(double t:times)total+=t;
printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"timing_region\":\"sum6_corrected_single_segment_attenuation_cases_repeat_completion\",\"jit_excluded\":true,\"internal_repeats\":1,\"native_reference_repaired\":true,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"},\"path_times_seconds\":[",trial,total,ok?"true":"false",art.size(),ma,path.c_str(),art.size());for(size_t i=0;i<times.size();++i)printf("%s%.17g",i?",":"",times[i]);printf("],\"case_internal_repeats\":[1,2,3,2,3,2],\"blocks\":128,\"threads\":128,\"active_segments_per_case\":1}\n");}
}
